#include <stdio.h>

#define MAX 1000000

static char composite[MAX + 1];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    if (n > MAX) n = MAX;
    if (n >= 2) {
        for (int i = 2; (long long)i * i <= n; ++i)
            if (!composite[i])
                for (int j = i * i; j <= n; j += i)
                    composite[j] = 1;
        for (int i = 2; i <= n; ++i)
            if (!composite[i])
                printf("%d\n", i);
    }
    return 0;
}

