int main(void) {
    size_t n = 0, cap = 64;
    char *s = malloc(cap);
    if (!s) return 1;

    int c;
    while ((c = getchar()) != EOF && c != '\n') {
        if (n == cap) {
            cap *= 2;
            char *t = realloc(s, cap);
            if (!t) {
                free(s);
                return 1;
            }
            s = t;
        }
        s[n++] = (char)c;
    }

    for (size_t i = n; i > 0; i--) putchar(s[i - 1]);
    putchar('\n');
    free(s);
    return 0;
}

