    int *t = malloc((n ? n : 1) * sizeof *t);
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    msort(a, t, 0, n);
    for (int i = 0; i < n; i++) {
        if (i) putchar(' ');
