#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int value; struct Node *next; } Node;

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Node *head = NULL, *tail = NULL;
    for (int i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) return 0;
        Node *p = malloc(sizeof *p);
        p->value = x;
        p->next = NULL;
        if (tail) tail->next = p;
        else head = p;
        tail = p;
    }

    Node **stack = malloc((n > 0 ? n : 1) * sizeof *stack);
    int top = 0;
    for (Node *p = head; p; p = p->next) stack[top++] = p;

    int first = 1;
    while (top > 0) {
        Node *p = stack[--top];
        if (!first) putchar(' ');
        printf("%d", p->value);
        first = 0;
    }
    putchar('\n');

    for (Node *p = head; p; ) { Node *q = p->next; free(p); p = q; }
    free(stack);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int val;
    struct Node *next;
} Node;

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Node *head = NULL, *tail = NULL;
    for (int i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) break;
        Node *node = malloc(sizeof *node);
        node->val = x;
        node->next = NULL;
        if (!head) head = tail = node;
        else {
            tail->next = node;
            tail = node;
        }
    }

    Node *prev = NULL, *cur = head;
    while (cur) {
        Node *next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    head = prev;

    for (cur = head; cur; cur = cur->next)
        printf("%d%c", cur->val, cur->next ? ' ' : '\n');

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *left, *right;
} Node;

static Node *make_node(int value) {
    Node *node = malloc(sizeof *node);
    node->value = value;
    node->left = node->right = NULL;
    return node;
}

static void insert(Node **root, int value) {
    while (*root) {
        root = value < (*root)->value ? &(*root)->left : &(*root)->right;
    }
    *root = make_node(value);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Node *root = NULL;
    for (int i = 0; i < n; ++i) {
        int x;
        if (scanf("%d", &x) != 1) return 0;
        insert(&root, x);
    }

    Node **stack = malloc((n > 0 ? n : 1) * sizeof *stack);
    int top = 0;
    Node *cur = root;
    int first = 1;

    while (cur || top) {
        while (cur) {
            stack[top++] = cur;
            cur = cur->left;
        }
        cur = stack[--top];
        if (!first) putchar(' ');
        first = 0;
        printf("%d", cur->value);
        cur = cur->right;
    }
    putchar('\n');

    free(stack);
    return 0;
}

#include <stdio.h>

int main(void) {
    int s[100], t = -1, x;
    char c;
    while (scanf(" %c", &c) == 1) {
        if (c == 'p') {
            if (scanf("%d", &x) == 1 && t < 99) s[++t] = x;
        } else if (c == 'o') {
            if (t >= 0) printf("%d\n", s[t--]);
        } else if (c == 'q') {
            break;
        }
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int buf[100];
    int head = 0, tail = 0, count = 0;
    char op;

    while (scanf(" %c", &op) == 1) {
        if (op == 'e') {
            int x;
            if (scanf("%d", &x) != 1) break;
            if (count < 100) {
                buf[tail] = x;
                tail = (tail + 1) % 100;
                count++;
            }
        } else if (op == 'd') {
            if (count > 0) {
                printf("%d\n", buf[head]);
                head = (head + 1) % 100;
                count--;
            }
        } else if (op == 'q') {
            break;
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    char c;
    struct Node *next;
} Node;

int main(void) {
    Node *head = NULL, *tail = NULL;
    int ch;
    while ((ch = getchar()) != EOF) {
        Node *n = malloc(sizeof *n);
        n->c = (char)ch;
        n->next = NULL;
        if (!tail) head = tail = n;
        else tail = tail->next = n;
        if (ch == '\n') break;
    }
    for (Node *p = head; p; p = p->next) putchar(p->c);
    while (head) {
        Node *t = head;
        head = head->next;
        free(t);
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int stack[256], top = 0;
    int c;
    while ((c = getchar()) != EOF) {
        if (c >= '0' && c <= '9') {
            stack[top++] = c - '0';
        } else if (c == '+' || c == '-' || c == '*' || c == '/') {
            int b = stack[--top];
            int a = stack[--top];
            if (c == '+') stack[top++] = a + b;
            else if (c == '-') stack[top++] = a - b;
            else if (c == '*') stack[top++] = a * b;
            else stack[top++] = a / b;
        }
    }
    if (top > 0) printf("%d\n", stack[top - 1]);
    return 0;
}

#include <stdio.h>

int main(void) {
    long long total = 0, term = 0;
    int op = 1, innum = 0;
    int c;
    while ((c = getchar()) != EOF) {
        if (c >= '0' && c <= '9') {
            term = term * 10 + (c - '0');
            innum = 1;
        } else if (c == '+' || c == '-') {
            if (innum) {
                total += (long long)op * term;
                term = 0;
                innum = 0;
            }
            op = (c == '+') ? 1 : -1;
        } else if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
            if (innum) {
                total += (long long)op * term;
                term = 0;
                innum = 0;
            }
        }
    }
    if (innum) total += (long long)op * term;
    printf("%lld\n", total);
    return 0;
}

