/* Integer-only floor(sqrt(n)) using binary search.
   The test (mid <= n / mid) is equivalent to (mid*mid <= n)
   but avoids overflow when mid is large. */
static unsigned long long isqrt_ull(unsigned long long n)
{
    unsigned long long lo = 0, hi = n, ans = 0;

    while (lo <= hi) {
        unsigned long long mid = lo + (hi - lo) / 2;
        int mid_square_le_n;

        if (mid == 0) {
            mid_square_le_n = 1; /* 0*0 == 0 <= n */
        } else {
            mid_square_le_n = (mid <= n / mid);
        }

        if (mid_square_le_n) {
            ans = mid;
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }

    return ans;
}

