/* Read one line from stdin into a dynamically allocated buffer.
   The trailing newline is consumed but not stored. */
static char *read_line(size_t *out_len)
{
    size_t cap = 128;
    size_t len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) {
        return NULL;
    }

    int c;
    while ((c = getchar()) != EOF && c != '\n') {
        /* Keep one byte free for the terminating '\0'. */
        if (len + 1 >= cap) {
            size_t new_cap = cap * 2;
            char *tmp = realloc(buf, new_cap);
            if (tmp == NULL) {
                free(buf);
                return NULL;
            }
            buf = tmp;
            cap = new_cap;
        }
        buf[len++] = (char)c;
    }

    /* Distinguish an empty input (EOF with no characters) from an empty line. */
    if (len == 0 && c == EOF) {
        free(buf);
        return NULL;
    }

    buf[len] = '\0';

    /* Remove a possible trailing carriage return from CRLF input. */
    if (len > 0 && buf[len - 1] == '\r') {
        buf[--len] = '\0';
    }

    *out_len = len;
    return buf;
}

