    /* Allow surrounding whitespace, but require hex digits in between. */
    size_t start = 0;
    while (start < (size_t)length && isspace((unsigned char)line[start])) {
        start++;
    }
    size_t end = (size_t)length;
    while (end > start && isspace((unsigned char)line[end - 1])) {
        end--;
    }

    for (size_t i = start; i < end; i++) {
        if (hex_digit_value(line[i]) < 0) {
            fprintf(stderr, "invalid hexadecimal digit: %c\n", line[i]);
            free(line);
            return 1;
        }
    }

    /* Store the decimal result as little-endian base-1e9 limbs. */
    size_t limb_count = 0;
    size_t limb_capacity = 16;
    unsigned int *limbs = calloc(limb_capacity, sizeof *limbs);
    if (limbs == NULL) {
        free(line);
        return 1;
    }

    for (size_t i = start; i < end; i++) {
        int digit = hex_digit_value(line[i]);
        unsigned long long carry = (unsigned long long)digit;

        /* Multiply the current number by 16 and add this hex digit. */
        for (size_t j = 0; j < limb_count; j++) {
            unsigned long long value = (unsigned long long)limbs[j] * 16 + carry;
            limbs[j] = (unsigned int)(value % BASE);
            carry = value / BASE;
        }

        while (carry > 0) {
            if (limb_count == limb_capacity) {
                limb_capacity *= 2;
                unsigned int *grown = realloc(limbs, limb_capacity * sizeof *grown);
                if (grown == NULL) {
                    free(limbs);
                    free(line);
                    return 1;
                }
                limbs = grown;
            }
            limbs[limb_count++] = (unsigned int)(carry % BASE);
            carry /= BASE;
        }
    }

    if (limb_count == 0) {
        puts("0");
    } else {
        printf("%u", limbs[limb_count - 1]);
        for (size_t i = limb_count - 1; i > 0; i--) {
            printf("%09u", limbs[i - 1]);
        }
        putchar('\n');
    }

    free(limbs);
    free(line);
    return 0;
}

