static int compare_ll(const void *a, const void *b) {
    const long long *pa = a;
    const long long *pb = b;
    /* Compare without subtracting, avoiding signed overflow. */
    if (*pa < *pb) return -1;
    if (*pa > *pb) return 1;
    return 0;
}

