        if (values == NULL)
            return 1;

        for (size_t i = 0; i < n; i++) {
            if (scanf("%d", &values[i]) != 1) {
                free(values);
                return 1;
            }
        }
    }

    /* Sorting makes equal values adjacent, so one pass can count each run. */
    qsort(values, n, sizeof *values, cmp_int);

    size_t i = 0;
    while (i < n) {
        size_t j = i + 1;

        /* Advance j past all values equal to values[i]. */
        while (j < n && values[j] == values[i])
            j++;

        /* Print the distinct value followed by its frequency. */
        printf("%d %zu\n", values[i], j - i);
        i = j;
    }

    free(values);
    return 0;
}

#include <stdio.h>

static int grid[10][10];
static int visited[10][10];

int main(void) {
    /* Read exactly 100 grid characters, ignoring all whitespace. */
    int n = 0;
    for (;;) {
        int ch = getchar();
        if (ch == EOF) break;
        if (ch == '.' || ch == '#') {
            grid[n / 10][n % 10] = (ch == '#');
            if (++n == 100) break;
        }
    }

    int components = 0;
    for (int r = 0; r < 10; r++) {
        for (int c = 0; c < 10; c++) {
            if (!grid[r][c] || visited[r][c]) continue;

            /* Start a new connected region. */
            components++;
            int stack[100][2];
            int sp = 0;
            stack[sp][0] = r;
            stack[sp][1] = c;
            sp++;
            visited[r][c] = 1;

            /* Iterative 4-neighbour flood fill. */
            while (sp > 0) {
                sp--;
                int cr = stack[sp][0];
                int cc = stack[sp][1];

                const int dr[4] = {-1, 1, 0, 0};
                const int dc[4] = {0, 0, -1, 1};

                for (int d = 0; d < 4; d++) {
                    int nr = cr + dr[d];
                    int nc = cc + dc[d];
                    if (nr < 0 || nr >= 10 || nc < 0 || nc >= 10) continue;
                    if (!grid[nr][nc] || visited[nr][nc]) continue;
                    visited[nr][nc] = 1;
                    stack[sp][0] = nr;
                    stack[sp][1] = nc;
                    sp++;
                }
            }
        }
    }

    printf("%d\n", components);
    return 0;
}

