int main(void) {
    int n;

    /* Read how many integers follow. */
    if (scanf("%d", &n) != 1 || n < 0) {
        return 1;
    }

    size_t count = 0;
    size_t capacity = n > 0 ? 1 : 0; /* Start with one slot; grow by doubling. */
    int *arr = capacity ? malloc(capacity * sizeof *arr) : NULL;

    if (n > 0 && arr == NULL) {
        return 1;
    }

    for (int i = 0; i < n; i++) {
        /* Double capacity before writing when the array is full. */
        if (count == capacity) {
            /* Guard against size_t overflow while doubling. */
            if (capacity > (SIZE_MAX / sizeof *arr) / 2) {
                free(arr);
                return 1;
            }
            size_t new_capacity = capacity * 2;
            int *tmp = realloc(arr, new_capacity * sizeof *arr);
            if (tmp == NULL) {
                free(arr);
                return 1;
            }
            arr = tmp;
            capacity = new_capacity;
        }

        if (scanf("%d", &arr[count]) != 1) {
            free(arr);
            return 1;
        }
        count++;
    }

    long long sum = 0;
    for (size_t i = 0; i < count; i++) {
        sum += arr[i];
    }

    printf("%lld\n", sum);

    free(arr);
    return 0;
}

