};

static struct Complex multiply(struct Complex a, struct Complex b) {
    /* (a + bi)(c + di) = (ac - bd) + (ad + bc)i */
    struct Complex result;
    result.re = a.re * b.re - a.im * b.im;
    result.im = a.re * b.im + a.im * b.re;
    return result;
}

