#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

/* Read every integer available on stdin into a dynamic array. */
static int read_all_ints(int **out_values, size_t *out_count) {
    size_t capacity = 16;
    size_t count = 0;
    int *values = malloc(capacity * sizeof *values);
    if (values == NULL) {
        return -1;
    }

    int x;
    for (;;) {
        int result = scanf("%d", &x);
        if (result == EOF) {
            break;
        }
        if (result != 1) {
            free(values);
            return -1;
        }

        if (count == capacity) {
            capacity *= 2;
            int *tmp = realloc(values, capacity * sizeof *values);
            if (tmp == NULL) {
                free(values);
                return -1;
            }
            values = tmp;
        }
        values[count++] = x;
    }

    *out_values = values;
    *out_count = count;
    return 0;
}

int main(void) {
    int *values = NULL;
    size_t count = 0;

    if (read_all_ints(&values, &count) != 0) {
        fprintf(stderr, "failed to read integers\n");
        return 1;
    }

    /* Build the list in input order by appending at the tail. */
    Node *head = NULL;
    Node *tail = NULL;
    for (size_t i = 0; i < count; i++) {
        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            fprintf(stderr, "out of memory\n");
            /* Cleanup is not strictly required before process exit. */
            return 1;
        }
        node->value = values[i];
        node->next = NULL;

        if (head == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
    }

    free(values);
    values = NULL;

    /*
     * Explicit stack array: push all node pointers while traversing,
     * then pop them to print the list in reverse order.
     */
    size_t stack_capacity = count > 0 ? count : 1;
    Node **stack = malloc(stack_capacity * sizeof *stack);
    if (stack == NULL) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }

    size_t top = 0;
    for (Node *p = head; p != NULL; p = p->next) {
        stack[top++] = p;
    }

    int first = 1;
    while (top > 0) {
        Node *node = stack[--top];
        if (!first) {
            putchar(' ');
        }
        first = 0;
        printf("%d", node->value);
        free(node);
    }
    putchar('\n');

    free(stack);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

/* Reverse the list in place by relinking each node's next pointer. */
static Node *reverse_list(Node *head) {
    Node *prev = NULL;
    Node *curr = head;

    while (curr != NULL) {
        Node *next = curr->next;  /* Save the rest of the list first. */
        curr->next = prev;        /* Point current node backward. */
        prev = curr;              /* Move prev forward. */
        curr = next;              /* Move curr forward. */
    }

    return prev;  /* prev is the new head after reversal. */
}

int main(void) {
    int n;

    if (scanf("%d", &n) != 1 || n < 0) {
        return 0;
    }

    Node *head = NULL;
    Node *tail = NULL;

    for (int i = 0; i < n; i++) {
        int value;

        if (scanf("%d", &value) != 1) {
            break;
        }

        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            perror("malloc");
            return 1;
        }

        node->value = value;
        node->next = NULL;

        if (tail != NULL) {
            tail->next = node;
        } else {
            head = node;
        }
        tail = node;
    }

    head = reverse_list(head);

    for (Node *p = head; p != NULL; p = p->next) {
        if (p != head) {
            putchar(' ');
        }
        printf("%d", p->value);
    }
    putchar('\n');

    /* Free the reversed list. */
    Node *p = head;
    while (p != NULL) {
        Node *next = p->next;
        free(p);
        p = next;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *left;
    struct Node *right;
} Node;

/* Allocate and initialize a new BST node. */
static Node *new_node(int value)
{
    Node *node = malloc(sizeof *node);
    if (node != NULL) {
        node->value = value;
        node->left = NULL;
        node->right = NULL;
    }
    return node;
}

/* Insert iteratively; duplicates go to the right subtree. */
static Node *insert(Node *root, int value)
{
    if (root == NULL) {
        return new_node(value);
    }

    Node *current = root;
    while (1) {
        if (value < current->value) {
            if (current->left == NULL) {
                current->left = new_node(value);
                break;
            }
            current = current->left;
        } else {
            if (current->right == NULL) {
                current->right = new_node(value);
                break;
            }
            current = current->right;
        }
    }
    return root;
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 0) {
        return 0;
    }

    Node *root = NULL;
    for (int i = 0; i < n; ++i) {
        int value;
        if (scanf("%d", &value) != 1) {
            return 0;
        }
        root = insert(root, value);
        if (root == NULL) {
            return 1;
        }
    }

    /* An explicit stack is needed because the tree may be skewed. */
    Node **stack = NULL;
    if (n > 0) {
        stack = malloc((size_t)n * sizeof *stack);
        if (stack == NULL) {
            return 1;
        }
    }

    int top = 0;
    Node *current = root;

    /* Standard iterative in-order traversal:
       push left spine, pop, visit, then process right subtree. */
    while (current != NULL || top > 0) {
        while (current != NULL) {
            stack[top++] = current;
            current = current->left;
        }

        current = stack[--top];
        printf("%d\n", current->value);
        current = current->right;
    }

    free(stack);
    return 0;
}

#include <stdio.h>

#define STACK_CAPACITY 100

int main(void) {
    int stack[STACK_CAPACITY];
    int top = -1; /* -1 means empty; valid indices are 0..CAPACITY-1 */

    char command;

    /* The leading space in " %c" skips whitespace, including newlines,
       so commands can be separated by spaces or line breaks. */
    while (scanf(" %c", &command) == 1) {
        if (command == 'p') {
            int value;
            if (scanf("%d", &value) != 1) {
                break; /* malformed push command */
            }

            /* Tricky part: only increment top after checking capacity,
               otherwise a full stack would write past the array end. */
            if (top == STACK_CAPACITY - 1) {
                fprintf(stderr, "stack overflow\n");
            } else {
                stack[++top] = value;
            }
        } else if (command == 'o') {
            /* Tricky part: check emptiness before decrementing top,
               so an empty stack is not read out of bounds. */
            if (top < 0) {
                fprintf(stderr, "stack underflow\n");
            } else {
                printf("%d\n", stack[top--]);
            }
        } else if (command == 'q') {
            break;
        }
    }

    return 0;
}

#include <stdio.h>

#define CAPACITY 100

typedef struct {
    int data[CAPACITY];
    int head;   /* index of next element to remove */
    int tail;   /* index where next element is inserted */
    int count;  /* number of stored elements */
} Queue;

static void queue_init(Queue *q)
{
    q->head = 0;
    q->tail = 0;
    q->count = 0;
}

/* Returns 1 on success, 0 if the queue is full. */
static int enqueue(Queue *q, int value)
{
    if (q->count == CAPACITY) {
        return 0;
    }
    q->data[q->tail] = value;
    q->tail = (q->tail + 1) % CAPACITY;  /* wrap around */
    q->count++;
    return 1;
}

/* Returns 1 on success, 0 if the queue is empty. */
static int dequeue(Queue *q, int *value)
{
    if (q->count == 0) {
        return 0;
    }
    *value = q->data[q->head];
    q->head = (q->head + 1) % CAPACITY;  /* wrap around */
    q->count--;
    return 1;
}

int main(void)
{
    Queue q;
    queue_init(&q);

    char command;
    while (scanf(" %c", &command) == 1) {
        if (command == 'e') {
            int value;
            if (scanf("%d", &value) != 1) {
                break;
            }
            enqueue(&q, value);  /* full queue is silently ignored */
        } else if (command == 'd') {
            int value;
            if (dequeue(&q, &value)) {
                printf("%d\n", value);
            }
        } else if (command == 'q') {
            break;
        }
    }

    return 0;
}

