#include <stdio.h>
#include <ctype.h>

#define STACK_SIZE 256

int main(void) {
    int stack[STACK_SIZE];
    int top = -1; /* -1 means the stack is empty */

    int c;
    while ((c = getchar()) != EOF) {
        if (isspace((unsigned char)c)) {
            continue; /* ignore spaces, tabs, and newlines */
        }

        if (isdigit((unsigned char)c)) {
            if (top == STACK_SIZE - 1) {
                fprintf(stderr, "stack overflow\n");
                return 1;
            }
            stack[++top] = c - '0';
        } else if (c == '+' || c == '-' || c == '*' || c == '/') {
            if (top < 1) {
                fprintf(stderr, "not enough operands\n");
                return 1;
            }

            /* Pop right operand first; the next popped value is the left operand. */
            int right = stack[top--];
            int left = stack[top--];
            int result;

            switch (c) {
                case '+': result = left + right; break;
                case '-': result = left - right; break;
                case '*': result = left * right; break;
                case '/':
                    if (right == 0) {
                        fprintf(stderr, "division by zero\n");
                        return 1;
                    }
                    /* Integer division truncates toward zero in C. */
                    result = left / right;
                    break;
                default:
                    fprintf(stderr, "invalid operator\n");
                    return 1;
            }

            stack[++top] = result;
        } else {
            fprintf(stderr, "invalid character: %c\n", c);
            return 1;
        }
    }

    if (top != 0) {
        fprintf(stderr, "invalid expression\n");
        return 1;
    }

    printf("%d\n", stack[top]);
    return 0;
}

#include <stdio.h>
#include <ctype.h>

int main(void) {
    long long result = 0;   /* accumulated answer */
    long long value = 0;    /* current number being read */
    long long sign = 1;     /* sign for the current number */
    int in_number = 0;      /* whether digits are being accumulated */
    int c;

    /*
     * Read one line character by character. Digits build the current
     * number; operators set its sign; other characters are ignored.
     * Crucially, a number is committed to result only when a non-digit
     * appears or the line ends.
     */
    while ((c = getchar()) != EOF && c != '\n') {
        if (isdigit((unsigned char)c)) {
            value = value * 10 + (c - '0');
            in_number = 1;
        } else {
            if (in_number) {
                result += sign * value;
                value = 0;
                in_number = 0;
            }
            if (c == '+') {
                sign = 1;
            } else if (c == '-') {
                sign = -1;
            } else if (isspace((unsigned char)c)) {
                /* ignore spaces/tabs/etc. */
            }
        }
    }

    /* Commit the final number if the line ended with digits. */
    if (in_number) {
        result += sign * value;
    }

    printf("%lld\n", result);
    return 0;
}

