/* qsort gives pointers to array elements; each element is char *,
   so cast through char *const * to reach the actual strings. */
static int cmp_words(const void *a, const void *b)
{
    const char *const *pa = a;
    const char *const *pb = b;
    return strcmp(*pa, *pb);
}

/* Read all of stdin into one NUL-terminated, dynamically grown buffer. */
static char *read_all_stdin(void)
{
    size_t cap = 4096;
    size_t len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) {
        return NULL;
    }

    for (;;) {
        if (len == cap) {
            if (cap > (size_t)-1 / 2) {
                free(buf);
                return NULL;
            }
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (tmp == NULL) {
                free(buf);
                return NULL;
            }
            buf = tmp;
        }

        size_t n = fread(buf + len, 1, cap - len, stdin);
        if (n == 0) {
            if (ferror(stdin)) {
                free(buf);
                return NULL;
            }
            break;
        }
        len += n;
    }

    /* Make room for the terminator if the buffer is exactly full. */
    if (len == cap) {
        char *tmp = realloc(buf, cap + 1);
        if (tmp == NULL) {
            free(buf);
            return NULL;
        }
        buf = tmp;
    }
    buf[len] = '\0';
    return buf;
}

int main(void)
{
    char *input = read_all_stdin();
    if (input == NULL) {
        fprintf(stderr, "error: could not read input\n");
        return 1;
    }

    /* strtok modifies the buffer in place and returns pointers into it. */
    const char *delimiters = " \t\n\r\f\v";
    char **words = NULL;
    size_t count = 0;
    size_t cap = 0;

    for (char *tok = strtok(input, delimiters); tok != NULL;
         tok = strtok(NULL, delimiters)) {
        if (count == cap) {
            size_t new_cap = cap == 0 ? 16 : cap * 2;
            char **tmp = realloc(words, new_cap * sizeof *words);
            if (tmp == NULL) {
                free(words);
                free(input);
                fprintf(stderr, "error: out of memory\n");
                return 1;
            }
            words = tmp;
            cap = new_cap;
        }
        words[count++] = tok;
    }

    qsort(words, count, sizeof *words, cmp_words);

    for (size_t i = 0; i < count; ++i) {
        if (i != 0) {
            putchar(' ');
        }
        fputs(words[i], stdout);
    }
    putchar('\n');

    free(words);
    free(input);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

static int roman_value(char c) {
    switch (c) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        case 'M': return 1000;
        default:  return -1;
    }
}

int main(void) {
    /* Read the entire input so an optional trailing newline is not a problem. */
    size_t capacity = 0, length = 0;
    char *input = NULL;
    int ch;

    while ((ch = fgetc(stdin)) != EOF) {
        if (length + 1 >= capacity) {
            size_t new_capacity = capacity ? capacity * 2 : 1024;
            char *tmp = realloc(input, new_capacity);
            if (tmp == NULL) {
                fprintf(stderr, "out of memory\n");
                free(input);
                return 1;
            }
            input = tmp;
            capacity = new_capacity;
        }
        input[length++] = (char)ch;
    }

    if (input == NULL) {
        input = calloc(1, 1);
        if (input == NULL) {
            fprintf(stderr, "out of memory\n");
            return 1;
        }
    }
    input[length] = '\0';

    /* Remove whitespace and accept lowercase input as well. */
    char *roman = malloc(length + 1);
    if (roman == NULL) {
        fprintf(stderr, "out of memory\n");
        free(input);
        return 1;
    }

    size_t count = 0;
    for (size_t i = 0; i < length; ++i) {
        if (!isspace((unsigned char)input[i])) {
            roman[count++] = (char)toupper((unsigned char)input[i]);
        }
    }
    roman[count] = '\0';

    /* Validate every remaining character. */
    for (size_t i = 0; i < count; ++i) {
        if (roman_value(roman[i]) < 0) {
            fprintf(stderr, "invalid Roman numeral character: %c\n", roman[i]);
            free(roman);
            free(input);
            return 1;
        }
    }

    /*
     * Subtractive notation: when a smaller value precedes a larger one,
     * subtract the smaller value instead of adding it.
     */
    long long total = 0;
    for (size_t i = 0; i < count; ++i) {
        int current = roman_value(roman[i]);
        int next = (i + 1 < count) ? roman_value(roman[i + 1]) : 0;
        if (current < next) {
            total -= current;
        } else {
            total += current;
        }
    }

    printf("%lld\n", total);

    free(roman);
    free(input);
    return 0;
}

