#include <stdio.h>
#include <stdlib.h>

/* Number of decimal digits in x, used to choose a fixed field width. */
static int decimal_width(unsigned long long x)
{
    char buf[32];
    return snprintf(buf, sizeof buf, "%llu", x);
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n <= 0) {
        return 0; /* No valid positive row count: print nothing. */
    }

    /* Store the triangle so the largest value (hence column width) is known. */
    unsigned long long **rows = malloc((size_t)n * sizeof *rows);
    if (rows == NULL) {
        return 1;
    }

    unsigned long long maxval = 1ULL;

    for (int i = 0; i < n; ++i) {
        rows[i] = malloc((size_t)(i + 1) * sizeof **rows);
        if (rows[i] == NULL) {
            for (int k = 0; k < i; ++k) {
                free(rows[k]);
            }
            free(rows);
            return 1;
        }

        rows[i][0] = 1ULL;
        rows[i][i] = 1ULL;

        for (int j = 1; j < i; ++j) {
            rows[i][j] = rows[i - 1][j - 1] + rows[i - 1][j];
            if (rows[i][j] > maxval) {
                maxval = rows[i][j];
            }
        }
    }

    int width = decimal_width(maxval);

    /* Last row has n values and n-1 gaps, so it is the widest row. */
    size_t last_width = (size_t)n * (size_t)width + (size_t)(n - 1);

    for (int i = 0; i < n; ++i) {
        size_t row_width = (size_t)(i + 1) * (size_t)width + (size_t)i;
        size_t leading = (last_width - row_width) / 2;

        /* Center this row under the widest (last) row. */
        for (size_t s = 0; s < leading; ++s) {
            putchar(' ');
        }

        for (int j = 0; j <= i; ++j) {
            printf("%*llu", width, rows[i][j]);
            if (j < i) {
                putchar(' '); /* One gap between values, none after the last. */
            }
        }
        putchar('\n');
    }

    for (int i = 0; i < n; ++i) {
        free(rows[i]);
    }
    free(rows);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) {
        return 0;
    }

    /* Store the matrix as one contiguous block to avoid VLA/portability issues. */
    long long *a = malloc((size_t)n * (size_t)n * sizeof *a);
    if (a == NULL) {
        return 1;
    }

    int top = 0, bottom = n - 1, left = 0, right = n - 1;
    long long value = 1;

    /* Peel off one rectangular border per iteration. */
    while (top <= bottom && left <= right) {
        for (int c = left; c <= right; ++c) {
            a[top * n + c] = value++;
        }
        ++top;

        for (int r = top; r <= bottom; ++r) {
            a[r * n + right] = value++;
        }
        --right;

        if (top <= bottom) {
            for (int c = right; c >= left; --c) {
                a[bottom * n + c] = value++;
            }
            --bottom;
        }

        if (left <= right) {
            for (int r = bottom; r >= top; --r) {
                a[r * n + left] = value++;
            }
            ++left;
        }
    }

    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < n; ++c) {
            printf("%lld%c", a[r * n + c], c + 1 < n ? ' ' : '\n');
        }
    }

    free(a);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Build the next look-and-say term from s. */
static char *next_term(const char *s)
{
    size_t len = strlen(s);

    /* Each run of equal digits needs at most 2 output characters. */
    size_t cap = len * 2 + 1;
    char *out = malloc(cap);
    if (out == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    size_t pos = 0;
    size_t i = 0;
    while (i < len) {
        char digit = s[i];
        size_t run = 0;
        while (i + run < len && s[i + run] == digit) {
            ++run;
        }
        i += run;

        char count[32];
        int count_len = snprintf(count, sizeof(count), "%zu", run);
        if (count_len < 0) {
            perror("snprintf");
            exit(EXIT_FAILURE);
        }

        memcpy(out + pos, count, (size_t)count_len);
        pos += (size_t)count_len;
        out[pos++] = digit;
    }
    out[pos] = '\0';
    return out;
}

int main(void)
{
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }
    if (n <= 0) {
        return 0;
    }

    char *term = malloc(2);
    if (term == NULL) {
        perror("malloc");
        return EXIT_FAILURE;
    }
    strcpy(term, "1");

    for (int i = 0; i < n; ++i) {
        puts(term);
        char *next = next_term(term);
        free(term);
        term = next;
    }

    free(term);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t cap = 128;
    size_t len = 0;
    char *line = malloc(cap);
    if (line == NULL) {
        return 1;
    }

    int c;
    /* Read one line manually so the program stays standard C11. */
    while ((c = getchar()) != EOF && c != '\n') {
        if (len + 1 >= cap) {
            size_t new_cap = cap * 2;
            char *tmp = realloc(line, new_cap);
            if (tmp == NULL) {
                free(line);
                return 1;
            }
            line = tmp;
            cap = new_cap;
        }
        line[len++] = (char)c;
    }

    /* Remove a trailing CR from CRLF line endings. */
    if (len > 0 && line[len - 1] == '\r') {
        len--;
    }

    if (len == 0) {
        free(line);
        return 0;
    }

    unsigned long counts[256] = {0};
    for (size_t i = 0; i < len; i++) {
        counts[(unsigned char)line[i]]++;
    }

    /* Strict '>' keeps the first occurring character when counts tie. */
    unsigned char best_char = (unsigned char)line[0];
    unsigned long best_count = counts[best_char];
    for (size_t i = 1; i < len; i++) {
        unsigned char ch = (unsigned char)line[i];
        if (counts[ch] > best_count) {
            best_count = counts[ch];
            best_char = ch;
        }
    }

    printf("%c %lu\n", best_char, best_count);
    free(line);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

/* Tricky: keep the function-pointer type consistent so a, s, and n
   can all be assigned to the same variable. */
static long long f_abs(long long x) { return x < 0 ? -x : x; }
static long long f_square(long long x) { return x * x; }
static long long f_negate(long long x) { return -x; }

int main(void) {
    char cmd;
    if (scanf(" %c", &cmd) != 1) {
        return 0;
    }

    /* Read every remaining integer into a buffer. This lets us support
       both "cmd x1 x2 ..." and "cmd count x1 x2 ..." input forms. */
    size_t cap = 16, count = 0;
    long long *values = malloc(cap * sizeof *values);
    if (!values) {
        return 1;
    }

    long long x;
    while (scanf("%lld", &x) == 1) {
        if (count == cap) {
            cap *= 2;
            long long *tmp = realloc(values, cap * sizeof *values);
            if (!tmp) {
                free(values);
                return 1;
            }
            values = tmp;
        }
        values[count++] = x;
    }

    long long (*op)(long long) = NULL;
    switch (cmd) {
        case 'a': op = f_abs; break;
        case 's': op = f_square; break;
        case 'n': op = f_negate; break;
        default: free(values); return 0;
    }

    /* If the first number is a count and exactly that many values follow,
       skip the count. Otherwise treat all remaining numbers as data. */
    size_t start = 0, total = count;
    if (count > 1 && values[0] >= 0 && (size_t)values[0] == count - 1) {
        start = 1;
        total = count - 1;
    }

    for (size_t i = 0; i < total; ++i) {
        printf("%lld\n", op(values[start + i]));
    }

    free(values);
    return 0;
}

