        if (number == LLONG_MIN) {
            magnitude = (unsigned long long)LLONG_MAX + 1ULL;
        } else {
            magnitude = (unsigned long long)(-number);
        }

        print_binary(magnitude);
    } else {
        print_binary((unsigned long long)number);
    }

    putchar('\n');
    return 0;
}

