static char *read_all_stdin(void) {
    size_t capacity = 4096;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return NULL;
    }

    int character;
    while ((character = fgetc(stdin)) != EOF) {
        if (length + 1 >= capacity) {
            size_t new_capacity = capacity + 4096;
            char *new_buffer = realloc(buffer, new_capacity);

            if (new_buffer == NULL) {
                free(buffer);
                return NULL;
            }

            buffer = new_buffer;
            capacity = new_capacity;
        }

        buffer[length++] = (char)character;
    }

    buffer[length] = '\0';
    return buffer;
}

static int count_set_bits_in_decimal_string(char *number, size_t length) {
    size_t start = 0;

    while (start + 1 < length && number[start] == '0') {
        start++;
    }

    char *current = number + start;
    size_t current_length = length - start;
    int set_bit_count = 0;

    while (!(current_length == 1 && current[0] == '0')) {
        int carry = 0;

        for (size_t index = 0; index < current_length; index++) {
            int value = carry * 10 + (current[index] - '0');
            current[index] = (char)('0' + value / 2);
            carry = value % 2;
        }

        if (carry != 0) {
            set_bit_count++;
        }

        while (current_length > 1 && current[0] == '0') {
            current++;
            current_length--;
        }
    }

    return set_bit_count;
}

int main(void) {
    char *input = read_all_stdin();

    if (input == NULL) {
        return 1;
    }

    size_t index = 0;

    while (input[index] != '\0' && isspace((unsigned char)input[index])) {
        index++;
    }

    if (input[index] == '+') {
        index++;
    }

    size_t start = index;

    while (input[index] != '\0' && isdigit((unsigned char)input[index])) {
        index++;
    }

    if (index == start) {
        printf("0\n");
        free(input);
        return 0;
    }

    input[index] = '\0';

    int result = count_set_bits_in_decimal_string(input + start, index - start);
    printf("%d\n", result);

    free(input);
    return 0;
}

#include <stdio.h>

static long long modular_power(long long base, long long exponent, long long modulus) {
    if (modulus <= 0) {
        return 0;
    }

    long long result = 1 % modulus;
    base %= modulus;
    if (base < 0) {
        base += modulus;
    }

    while (exponent > 0) {
        if (exponent & 1) {
            result = result * base % modulus;
        }
        base = base * base % modulus;
        exponent >>= 1;
    }

    return result;
}

int main(void) {
    long long base;
    long long exponent;
    long long modulus;

    if (scanf("%lld %lld %lld", &base, &exponent, &modulus) != 3) {
        return 0;
    }

    if (exponent < 0) {
        return 0;
    }

    printf("%lld\n", modular_power(base, exponent, modulus));
    return 0;
}

