static long long proper_divisor_sum(long long number)
{
    if (number <= 1) {
        return 0;
    }

    long long sum = 1;

    for (long long factor = 2; factor <= number / factor; ++factor) {
        if (number % factor == 0) {
            long long paired_divisor = number / factor;
            if (factor == paired_divisor) {
                sum += factor;
            } else {
                sum += factor + paired_divisor;
            }
        }
    }

    return sum;
}

