    if (scanf("%lld", &n) != 1) {
        return 0;
    }

    if (n < 0) {
        n = -n;
    }

    printf("%lld\n", proper_divisor_sum(n));
    return 0;
}

#include <stdio.h>

static long long collatz_length(long long n) {
    long long steps = 0;
    __int128 x = n;
    while (x != 1) {
        if (x % 2 == 0) {
            x /= 2;
        } else {
            x = 3 * x + 1;
        }
        steps++;
    }
    return steps + 1; /* include both endpoints */
}

int main(void) {
    long long n;
    if (scanf("%lld", &n) != 1) {
        return 1;
    }
    if (n < 1) {
        return 1;
    }
    printf("%lld\n", collatz_length(n));
    return 0;
}

#include <stdio.h>

static long long compute_totient(long long n)
{
    long long result = n;

    if (n % 2 == 0) {
        result -= result / 2;
        while (n % 2 == 0) {
            n /= 2;
        }
    }

    for (long long factor = 3; factor <= n / factor; factor += 2) {
        if (n % factor == 0) {
            result -= result / factor;
            while (n % factor == 0) {
                n /= factor;
            }
        }
    }

    if (n > 1) {
        result -= result / n;
    }

    return result;
}

int main(void)
{
    long long n;

    if (scanf("%lld", &n) != 1) {
        return 1;
    }

    if (n <= 0) {
        return 1;
    }

    printf("%lld\n", compute_totient(n));
    return 0;
}

#include <stdio.h>

static long long compute_power(int base, int exponent)
{
    long long result = 1;

    for (int i = 0; i < exponent; ++i) {
        result *= base;
    }

    return result;
}

int main(void)
{
    int base;
    int exponent;

    if (scanf("%d %d", &base, &exponent) != 2) {
        fprintf(stderr, "Expected two integers\n");
        return 1;
    }

    if (exponent < 0) {
        fprintf(stderr, "Exponent must be non-negative\n");
        return 1;
    }

    printf("%lld\n", compute_power(base, exponent));
    return 0;
}

#include <stdio.h>
#include <stdbool.h>

static bool is_perfect_square(long long value) {
    if (value < 0) {
        return false;
    }

    unsigned long long number = (unsigned long long)value;

    if (number < 2) {
        return true;
    }

    unsigned long long low = 1;
    unsigned long long high = number / 2 + 1;

    while (low <= high) {
        unsigned long long middle = low + (high - low) / 2;
        unsigned long long square;

        if (middle <= number / middle) {
            square = middle * middle;
        } else {
            square = number + 1;
        }

        if (square == number) {
            return true;
        }

        if (square < number) {
            low = middle + 1;
        } else {
            high = middle - 1;
        }
    }

    return false;
}

int main(void) {
    long long n;

    if (scanf("%lld", &n) != 1) {
        return 1;
    }

    printf("%s\n", is_perfect_square(n) ? "true" : "false");
    return 0;
}

#include <stdio.h>

static int largest_power_of_two(int value)
{
    if (value <= 0) {
        return 0;
    }

    int result = 1;
    while (result <= value / 2) {
        result <<= 1;
    }

    return result;
}

int main(void)
{
    int number;

    if (scanf("%d", &number) != 1) {
        return 1;
    }

    printf("%d\n", largest_power_of_two(number));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static char *read_all_input(size_t *length_out)
{
    size_t capacity = 1;
    size_t length = 0;
    char *data = malloc(capacity);

    if (data == NULL) {
        return NULL;
    }

    int character;
    while ((character = getchar()) != EOF) {
        if (length + 1 >= capacity) {
            size_t new_capacity = capacity * 2;
            if (new_capacity < capacity) {
                free(data);
                return NULL;
            }

            char *new_data = realloc(data, new_capacity);
            if (new_data == NULL) {
                free(data);
                return NULL;
            }

            data = new_data;
            capacity = new_capacity;
        }

        data[length++] = (char)character;
    }

    data[length] = '\0';
    *length_out = length;
    return data;
}

static void reverse_characters(char *text, size_t count)
{
    if (count < 2) {
        return;
    }

    char *left = text;
    char *right = text + count - 1;

    while (left < right) {
        char temporary = *left;
        *left = *right;
        *right = temporary;
        left++;
        right--;
    }
}

int main(void)
{
    size_t input_length = 0;
    char *input = read_all_input(&input_length);

    if (input == NULL) {
        return EXIT_FAILURE;
    }

    size_t content_length = input_length;
    int had_trailing_newline = 0;

    if (content_length > 0 && input[content_length - 1] == '\n') {
        content_length--;
        had_trailing_newline = 1;
    }

    reverse_characters(input, content_length);

    if (had_trailing_newline) {
        input[content_length] = '\n';
    }

    size_t output_length = content_length + (had_trailing_newline ? 1 : 0);

    if (fwrite(input, 1, output_length, stdout) != output_length) {
        free(input);
        return EXIT_FAILURE;
    }

    free(input);
    return EXIT_SUCCESS;
}

