#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *read_line(void)
{
    size_t capacity = 64;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return NULL;
    }

    int character;
    while ((character = getchar()) != EOF && character != '\n') {
        if (length + 1 >= capacity) {
            capacity *= 2;
            char *resized = realloc(buffer, capacity);
            if (resized == NULL) {
                free(buffer);
                return NULL;
            }
            buffer = resized;
        }
        buffer[length++] = (char)character;
    }

    buffer[length] = '\0';
    return buffer;
}

static int is_palindrome_ignoring_spaces(const char *text)
{
    size_t left = 0;
    size_t right = strlen(text);

    while (left < right) {
        while (left < right && text[left] == ' ') {
            left++;
        }
        while (left < right && text[right - 1] == ' ') {
            right--;
        }
        if (left >= right) {
            break;
        }
        if (text[left] != text[right - 1]) {
            return 0;
        }
        left++;
        right--;
    }

    return 1;
}

int main(void)
{
    char *line = read_line();

    if (line == NULL) {
        return 1;
    }

    printf("%d\n", is_palindrome_ignoring_spaces(line));
    free(line);
    return 0;
}

#include <stdio.h>
#include <ctype.h>

static int is_vowel(int character)
{
    char lower = (char)tolower((unsigned char)character);
    return lower == 'a' || lower == 'e' || lower == 'i' ||
           lower == 'o' || lower == 'u';
}

static int count_vowels_in_first_line(void)
{
    int vowel_count = 0;
    int character;

    while ((character = getchar()) != EOF && character != '\n') {
        if (is_vowel(character)) {
            vowel_count++;
        }
    }

    return vowel_count;
}

int main(void)
{
    int total_vowels = count_vowels_in_first_line();
    printf("%d\n", total_vowels);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int shift_lowercase(int character)
{
    if (character >= 'a' && character <= 'z') {
        return character == 'z' ? 'a' : character + 1;
    }
    return character;
}

static char *read_one_line(void)
{
    size_t capacity = 64;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return NULL;
    }

    int character;
    while ((character = getchar()) != EOF && character != '\n') {
        if (length + 1 >= capacity) {
            size_t new_capacity = capacity * 2;
            char *new_buffer = realloc(buffer, new_capacity);

            if (new_buffer == NULL) {
                free(buffer);
                return NULL;
            }

            buffer = new_buffer;
            capacity = new_capacity;
        }

        buffer[length++] = (char)character;
    }

    if (character == '\n') {
        if (length + 1 >= capacity) {
            size_t new_capacity = capacity * 2;
            char *new_buffer = realloc(buffer, new_capacity);

            if (new_buffer == NULL) {
                free(buffer);
                return NULL;
            }

            buffer = new_buffer;
            capacity = new_capacity;
        }

        buffer[length++] = '\n';
    }

    if (length == 0 && character == EOF) {
        free(buffer);
        return NULL;
    }

    buffer[length] = '\0';
    return buffer;
}

static void print_shifted_line(const char *line)
{
    for (const char *pointer = line; *pointer != '\0'; ++pointer) {
        putchar(shift_lowercase((unsigned char)*pointer));
    }
}

int main(void)
{
    char *line = read_one_line();

    if (line != NULL) {
        print_shifted_line(line);
        free(line);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int count_words(const char *line) {
    int count = 0;
    int in_word = 0;
    for (size_t i = 0; line[i] != '\0'; i++) {
        if (line[i] == ' ') {
            in_word = 0;
        } else {
            if (!in_word) {
                count++;
                in_word = 1;
            }
        }
    }
    return count;
}

int main(void) {
    char *line = NULL;
    size_t capacity = 0;
    ssize_t length = getline(&line, &capacity, stdin);
    if (length == -1) {
        free(line);
        printf("0\n");
        return 0;
    }
    printf("%d\n", count_words(line));
    free(line);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

static char *read_one_line(FILE *stream)
{
    size_t capacity = 128;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return NULL;
    }

    int character;
    while ((character = fgetc(stream)) != EOF && character != '\n') {
        if (length + 1 >= capacity) {
            size_t new_capacity = capacity * 2;
            char *new_buffer = realloc(buffer, new_capacity);

            if (new_buffer == NULL) {
                free(buffer);
                return NULL;
            }

            buffer = new_buffer;
            capacity = new_capacity;
        }

        buffer[length++] = (char)character;
    }

    if (character == EOF && length == 0) {
        free(buffer);
        return NULL;
    }

    buffer[length] = '\0';
    return buffer;
}

static void print_longest_word(const char *line)
{
    size_t best_start = 0;
    size_t best_length = 0;
    size_t index = 0;

    while (line[index] != '\0') {
        while (isspace((unsigned char)line[index])) {
            ++index;
        }

        size_t word_start = index;
        while (line[index] != '\0' && !isspace((unsigned char)line[index])) {
            ++index;
        }

        size_t word_length = index - word_start;
        if (word_length > best_length) {
            best_start = word_start;
            best_length = word_length;
        }
    }

    if (best_length > 0) {
        fwrite(line + best_start, 1, best_length, stdout);
    }
    putchar('\n');
}

int main(void)
{
    char *line = read_one_line(stdin);

    if (line != NULL) {
        print_longest_word(line);
        free(line);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static char *read_all_stdin(void) {
    size_t capacity = 64;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return NULL;
    }

    int character;
    while ((character = fgetc(stdin)) != EOF) {
        if (length + 1 >= capacity) {
            size_t new_capacity = capacity * 2;
            char *new_buffer = realloc(buffer, new_capacity);
            if (new_buffer == NULL) {
                free(buffer);
                return NULL;
            }
            buffer = new_buffer;
            capacity = new_capacity;
        }
        buffer[length++] = (char)character;
    }

    buffer[length] = '\0';
    return buffer;
}

static void remove_spaces_in_place(char *text) {
    char *source = text;
    char *destination = text;

    while (*source != '\0') {
        if (*source != ' ') {
            *destination = *source;
            destination++;
        }
        source++;
    }

    *destination = '\0';
}

int main(void) {
    char *input = read_all_stdin();

    if (input == NULL) {
        return 1;
    }

    remove_spaces_in_place(input);
    fputs(input, stdout);
    free(input);

    return 0;
}

#include <stdio.h>

int main(void) {
    int current = 0;
    size_t run_length = 0;
    int has_run = 0;
    int character;

    while ((character = getchar()) != EOF && character != '\n') {
        if (!has_run) {
            current = character;
            run_length = 1;
            has_run = 1;
        } else if (character == current) {
            ++run_length;
        } else {
            printf("%c%zu", current, run_length);
            current = character;
            run_length = 1;
        }
    }

    if (has_run) {
        printf("%c%zu", current, run_length);
    }
    putchar('\n');

    return 0;
}

#include <stdio.h>

static int line_is_balanced(void)
{
    int depth = 0;
    int saw_negative = 0;
    int character;

    while ((character = getchar()) != '\n' && character != EOF) {
        if (character == '(') {
            depth++;
        } else if (character == ')') {
            depth--;
            if (depth < 0) {
                saw_negative = 1;
            }
        }
    }

    return !saw_negative && depth == 0;
}

int main(void)
{
    printf("%d\n", line_is_balanced() ? 1 : 0);
    return 0;
}

#include <stdio.h>

static size_t count_lines(FILE *input_stream)
{
    size_t line_count = 0;
    int has_unterminated_line = 0;
    int current_character;

    while ((current_character = fgetc(input_stream)) != EOF) {
        has_unterminated_line = 1;
        if (current_character == '\n') {
            ++line_count;
            has_unterminated_line = 0;
        }
    }

    if (has_unterminated_line) {
        ++line_count;
    }

    return line_count;
}

int main(void)
{
    size_t total_lines = count_lines(stdin);
    printf("%zu\n", total_lines);
    return 0;
}

