#include <stdio.h>

#define ALPHABET_SIZE 26

static void count_lowercase_letters(FILE *input, int counts[ALPHABET_SIZE])
{
    int character;

    while ((character = fgetc(input)) != EOF) {
        if (character >= 'a' && character <= 'z') {
            counts[character - 'a']++;
        }
    }
}

static void print_nonzero_counts(const int counts[ALPHABET_SIZE])
{
    int needs_space = 0;

    for (int index = 0; index < ALPHABET_SIZE; ++index) {
        if (counts[index] == 0) {
            continue;
        }

        if (needs_space) {
            putchar(' ');
        }

        printf("%c:%d", 'a' + index, counts[index]);
        needs_space = 1;
    }

    putchar('\n');
}

int main(void)
{
    int counts[ALPHABET_SIZE] = {0};

    count_lowercase_letters(stdin, counts);
    print_nonzero_counts(counts);

    return 0;
}

#include <stdio.h>

static void count_line_characters(int character_counts[256]) {
    int character;

    while ((character = getchar()) != EOF && character != '\n') {
        character_counts[(unsigned char)character]++;
    }
}

static void print_sorted_characters(const int character_counts[256]) {
    for (int ascii_value = 0; ascii_value < 256; ascii_value++) {
        for (int occurrence = 0; occurrence < character_counts[ascii_value]; occurrence++) {
            putchar(ascii_value);
        }
    }
    putchar('\n');
}

int main(void) {
    int character_counts[256] = {0};

    count_line_characters(character_counts);
    print_sorted_characters(character_counts);

    return 0;
}

#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned char *digits;
    size_t length;
    size_t capacity;
} DecimalNumber;

static void decimal_init(DecimalNumber *number) {
    number->capacity = 16;
    number->length = 1;
    number->digits = calloc(number->capacity, 1);
    if (number->digits == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }
}

static void decimal_free(DecimalNumber *number) {
    free(number->digits);
}

static void decimal_ensure_capacity(DecimalNumber *number, size_t minimum) {
    if (number->capacity >= minimum) {
        return;
    }
    size_t new_capacity = number->capacity;
    while (new_capacity < minimum) {
        new_capacity *= 2;
    }
    unsigned char *new_digits = calloc(new_capacity, 1);
    if (new_digits == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }
    memcpy(new_digits, number->digits, number->length);
    free(number->digits);
    number->digits = new_digits;
    number->capacity = new_capacity;
}

static void decimal_normalize(DecimalNumber *number) {
    while (number->length > 1 && number->digits[number->length - 1] == 0) {
        number->length--;
    }
}

static void decimal_multiply_by_small(DecimalNumber *number, unsigned int factor) {
    unsigned int carry = 0;
    for (size_t i = 0; i < number->length; ++i) {
        unsigned int product = number->digits[i] * factor + carry;
        number->digits[i] = (unsigned char)(product % 10);
        carry = product / 10;
    }
    while (carry > 0) {
        decimal_ensure_capacity(number, number->length + 1);
        number->digits[number->length] = (unsigned char)(carry % 10);
        number->length++;
        carry /= 10;
    }
    decimal_normalize(number);
}

static void decimal_add_small(DecimalNumber *number, unsigned int value) {
    unsigned int carry = value;
    size_t position = 0;
    while (carry > 0) {
        decimal_ensure_capacity(number, position + 1);
        if (position >= number->length) {
            number->digits[position] = 0;
            number->length = position + 1;
        }
        unsigned int sum = number->digits[position] + carry;
        number->digits[position] = (unsigned char)(sum % 10);
        carry = sum / 10;
        position++;
    }
    decimal_normalize(number);
}

static int hex_digit_value(char digit) {
    if (digit >= '0' && digit <= '9') {
        return digit - '0';
    }
    if (digit >= 'a' && digit <= 'f') {
        return digit - 'a' + 10;
    }
    if (digit >= 'A' && digit <= 'F') {
        return digit - 'A' + 10;
    }
    return 0;
}

static DecimalNumber *decimal_from_hex(const char *hex_text) {
    DecimalNumber *number = malloc(sizeof *number);
    if (number == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }
    decimal_init(number);
    for (const char *cursor = hex_text; *cursor != '\0'; ++cursor) {
        decimal_multiply_by_small(number, 16);
        decimal_add_small(number, (unsigned int)hex_digit_value(*cursor));
    }
    decimal_normalize(number);
    return number;
}

static char *read_all_input(void) {
    size_t capacity = 4096;
    size_t length = 0;
    char *buffer = malloc(capacity);
    if (buffer == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }
    int character;
    while ((character = fgetc(stdin)) != EOF) {
        if (length + 1 >= capacity) {
            capacity *= 2;
            char *new_buffer = realloc(buffer, capacity);
            if (new_buffer == NULL) {
                fprintf(stderr, "out of memory\n");
                exit(EXIT_FAILURE);
            }
            buffer = new_buffer;
        }
        buffer[length++] = (char)character;
    }
    buffer[length] = '\0';
    return buffer;
}

static int extract_hex_digits(const char *input, char **hex_text) {
    const char *cursor = input;
    while (isspace((unsigned char)*cursor)) {
        cursor++;
    }
    if (cursor[0] == '0' && (cursor[1] == 'x' || cursor[1] == 'X')) {
        cursor += 2;
    }

    size_t capacity = 16;
    size_t length = 0;
    char *text = malloc(capacity);
    if (text == NULL) {
        return 0;
    }

    int has_digit = 0;
    while (isxdigit((unsigned char)*cursor)) {
        if (length + 1 >= capacity) {
            capacity *= 2;
            char *new_text = realloc(text, capacity);
            if (new_text == NULL) {
                free(text);
                return 0;
            }
            text = new_text;
        }
        text[length++] = *cursor;
        cursor++;
        has_digit = 1;
    }

    while (isspace((unsigned char)*cursor)) {
        cursor++;
    }
    if (*cursor != '\0') {
        free(text);
        return 0;
    }

    text[length] = '\0';
    (void)has_digit;
    *hex_text = text;
    return 1;
}

static void decimal_print(const DecimalNumber *number) {
    if (number->length == 0) {
        putchar('0');
        return;
    }
    for (size_t i = number->length; i > 0; --i) {
        putchar('0' + number->digits[i - 1]);
    }
}

int main(void) {
    char *input = read_all_input();
    char *hex_text = NULL;

    if (!extract_hex_digits(input, &hex_text)) {
        fprintf(stderr, "invalid input\n");
        free(input);
        return EXIT_FAILURE;
    }

    DecimalNumber *value = decimal_from_hex(hex_text);
    decimal_print(value);
    putchar('\n');

    decimal_free(value);
    free(value);
    free(hex_text);
    free(input);
    return EXIT_SUCCESS;
}

