static int line_is_all_digits(FILE *stream) {
    char buffer[4096];
    int all_digits = 1;
    int saw_digit = 0;
    int finished = 0;

    while (!finished) {
        size_t count = fread(buffer, 1, sizeof(buffer), stream);

        if (count == 0) {
            if (ferror(stream)) {
                return 0;
            }
            break;
        }

        for (size_t index = 0; index < count; ++index) {
            unsigned char character = (unsigned char)buffer[index];

            if (character == '\n') {
                finished = 1;
                break;
            }

            if (character < '0' || character > '9') {
                all_digits = 0;
            } else {
                saw_digit = 1;
            }
        }
    }

    return all_digits && saw_digit;
}

int main(void) {
    int result = line_is_all_digits(stdin);
    printf("%d\n", result);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static void bubble_sort(int *values, size_t count)
{
    for (size_t pass = 0; pass + 1 < count; ++pass) {
        int swapped = 0;
        for (size_t index = 0; index + 1 < count - pass; ++index) {
            if (values[index] > values[index + 1]) {
                int temporary = values[index];
                values[index] = values[index + 1];
                values[index + 1] = temporary;
                swapped = 1;
            }
        }
        if (!swapped) {
            break;
        }
    }
}

static void print_values(const int *values, size_t count)
{
    for (size_t index = 0; index < count; ++index) {
        if (index > 0) {
