        printf("%d", values[index]);
    }
    putchar('\n');
}

int main(void)
{
    int count;

    if (scanf("%d", &count) != 1 || count < 0) {
        return 1;
    }

    int *values = malloc((size_t)count * sizeof *values);
    if (count > 0 && values == NULL) {
        return 1;
    }

    for (int index = 0; index < count; ++index) {
        if (scanf("%d", &values[index]) != 1) {
            free(values);
            return 1;
        }
    }

    bubble_sort(values, (size_t)count);
    print_values(values, (size_t)count);

    free(values);
    return 0;
}

