static void insertion_sort(int *values, size_t count) {
    for (size_t index = 1; index < count; ++index) {
        int key = values[index];
        size_t position = index;

        while (position > 0 && values[position - 1] > key) {
            values[position] = values[position - 1];
            --position;
        }
        values[position] = key;
    }
}

