#include <stdio.h>
#include <stdlib.h>

static void swap_int(int *left, int *right)
{
    int temporary_value = *left;
    *left = *right;
    *right = temporary_value;
}

static void quicksort_values(int *values, size_t low, size_t high)
{
    if (high - low < 2) {
        return;
    }

    int pivot = values[low + (high - low) / 2];
    size_t less_than = low;
    size_t greater_than = high;
    size_t current = low;

    while (current < greater_than) {
        if (values[current] < pivot) {
            swap_int(&values[less_than], &values[current]);
            ++less_than;
            ++current;
        } else if (values[current] > pivot) {
            --greater_than;
            swap_int(&values[current], &values[greater_than]);
        } else {
            ++current;
        }
    }

    quicksort_values(values, low, less_than);
    quicksort_values(values, greater_than, high);
}

int main(void)
{
    int requested_count;

    if (scanf("%d", &requested_count) != 1 || requested_count < 0) {
        return EXIT_FAILURE;
    }

    size_t count = (size_t)requested_count;
    size_t allocation_count = count == 0 ? 1 : count;
    int *values = malloc(allocation_count * sizeof *values);

    if (values == NULL) {
        return EXIT_FAILURE;
    }

    for (size_t index = 0; index < count; ++index) {
        if (scanf("%d", &values[index]) != 1) {
            free(values);
            return EXIT_FAILURE;
        }
    }

    quicksort_values(values, 0, count);

    for (size_t index = 0; index < count; ++index) {
        if (index != 0) {
            putchar(' ');
        }
        printf("%d", values[index]);
    }

    if (count != 0) {
        putchar('\n');
    }

    free(values);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static void merge_ranges(int *values, int *helper, int left, int middle, int right) {
    int i = left;
    int j = middle + 1;
    int k = left;

    while (i <= middle && j <= right) {
        if (values[i] <= values[j]) {
            helper[k++] = values[i++];
        } else {
            helper[k++] = values[j++];
        }
    }

    while (i <= middle) {
        helper[k++] = values[i++];
    }

    while (j <= right) {
        helper[k++] = values[j++];
    }

    for (i = left; i <= right; i++) {
        values[i] = helper[i];
    }
}

static void merge_sort_range(int *values, int *helper, int left, int right) {
    if (left >= right) {
        return;
    }

    int middle = left + (right - left) / 2;
    merge_sort_range(values, helper, left, middle);
    merge_sort_range(values, helper, middle + 1, right);
    merge_ranges(values, helper, left, middle, right);
}

int main(void) {
    int count;

    if (scanf("%d", &count) != 1 || count < 0) {
        fprintf(stderr, "Invalid input count\n");
        return 1;
    }

    int *values = NULL;
    int *helper = NULL;

    if (count > 0) {
        values = malloc((size_t)count * sizeof *values);
        helper = malloc((size_t)count * sizeof *helper);

        if (values == NULL || helper == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            free(values);
            free(helper);
            return 1;
        }

        for (int i = 0; i < count; i++) {
            if (scanf("%d", &values[i]) != 1) {
                fprintf(stderr, "Invalid input value\n");
                free(values);
                free(helper);
                return 1;
            }
        }

        merge_sort_range(values, helper, 0, count - 1);
    }

    for (int i = 0; i < count; i++) {
        if (i > 0) {
            putchar(' ');
        }
        printf("%d", values[i]);
    }
    putchar('\n');

    free(values);
    free(helper);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static void sift_down(int *values, int start_index, int end_index)
{
    int parent = start_index;

    while (2 * parent + 1 <= end_index) {
        int child = 2 * parent + 1;

        if (child + 1 <= end_index && values[child] < values[child + 1]) {
            child++;
        }

        if (values[parent] < values[child]) {
            int temporary = values[parent];
            values[parent] = values[child];
            values[child] = temporary;
            parent = child;
        } else {
            break;
        }
    }
}

static void heap_sort(int *values, int count)
{
    for (int heap_index = count / 2 - 1; heap_index >= 0; heap_index--) {
        sift_down(values, heap_index, count - 1);
    }

    for (int last_index = count - 1; last_index > 0; last_index--) {
        int temporary = values[0];
        values[0] = values[last_index];
        values[last_index] = temporary;

        sift_down(values, 0, last_index - 1);
    }
}

int main(void)
{
    int count;

    if (scanf("%d", &count) != 1 || count < 0) {
        return 1;
    }

    int *values = NULL;
    if (count > 0) {
        values = malloc((size_t)count * sizeof(*values));
        if (values == NULL) {
            return 1;
        }
    }

    for (int index = 0; index < count; index++) {
        if (scanf("%d", &values[index]) != 1) {
            free(values);
            return 1;
        }
    }

    heap_sort(values, count);

    for (int index = 0; index < count; index++) {
        if (index > 0) {
            putchar(' ');
        }
        printf("%d", values[index]);
    }
    putchar('\n');

    free(values);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int binary_search(const int *values, int count, int target)
{
    int low = 0;
    int high = count - 1;

    while (low <= high) {
        int middle = low + (high - low) / 2;

        if (values[middle] == target) {
            return middle;
        }
        if (values[middle] < target) {
            low = middle + 1;
        } else {
            high = middle - 1;
        }
    }

    return -1;
}

int main(void)
{
    int count;

    if (scanf("%d", &count) != 1 || count < 0) {
        return 1;
    }

    int *values = NULL;
    if (count > 0) {
        values = malloc((size_t)count * sizeof *values);
        if (values == NULL) {
            return 1;
        }

        for (int i = 0; i < count; i++) {
            if (scanf("%d", &values[i]) != 1) {
                free(values);
                return 1;
            }
        }
    }

    int target;
    if (scanf("%d", &target) != 1) {
        free(values);
        return 1;
    }

    printf("%d\n", binary_search(values, count, target));
    free(values);
    return 0;
}

#include <stdio.h>

static int read_long_long(long long *value)
{
    return scanf("%lld", value) == 1;
}

int main(void)
{
    long long count;
    if (!read_long_long(&count) || count < 2) {
        return 1;
    }

    long long first_value;
    long long second_value;
    if (!read_long_long(&first_value) || !read_long_long(&second_value)) {
        return 1;
    }

    long long largest = first_value > second_value ? first_value : second_value;
    long long second_largest = first_value > second_value ? second_value : first_value;

    for (long long i = 2; i < count; ++i) {
        long long current_value;
        if (!read_long_long(&current_value)) {
            return 1;
        }

        if (current_value > largest) {
            second_largest = largest;
            largest = current_value;
        } else if (current_value > second_largest) {
            second_largest = current_value;
        }
    }

    printf("%lld %lld\n", largest, second_largest);
    return 0;
}

