static int read_count(void)
{
    int count;

    if (scanf("%d", &count) != 1 || count < 0) {
        return -1;
    }
    return count;
}

static int print_prefix_sums(int count)
{
    long long prefix = 0;

    for (int i = 0; i < count; ++i) {
        long long value;

        if (scanf("%lld", &value) != 1) {
            return -1;
        }

        prefix += value;

        if (i > 0) {
            putchar(' ');
        }
        printf("%lld", prefix);
    }

    putchar('\n');
    return 0;
}

int main(void)
{
    int count = read_count();

    if (count < 0) {
        return EXIT_FAILURE;
    }

    if (print_prefix_sums(count) != 0) {
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

