        for (int column = 0; column < MATRIX_SIZE; column++) {
            scanf("%lf", &matrix->values[row][column]);
        }
    }
}

static void multiply_matrices(const Matrix *left, const Matrix *right, Matrix *result)
{
    for (int row = 0; row < MATRIX_SIZE; row++) {
        for (int column = 0; column < MATRIX_SIZE; column++) {
            double sum = 0.0;

            for (int k = 0; k < MATRIX_SIZE; k++) {
                sum += left->values[row][k] * right->values[k][column];
            }

            result->values[row][column] = sum;
        }
    }
}

static void print_matrix(const Matrix *matrix)
{
