#include <stdio.h>

#define GRID_SIZE 10

static int is_inside(int row, int col)
{
    return row >= 0 && row < GRID_SIZE && col >= 0 && col < GRID_SIZE;
}

static void flood_fill(char grid[GRID_SIZE][GRID_SIZE + 1], int start_row, int start_col)
{
    int stack_row[GRID_SIZE * GRID_SIZE];
    int stack_col[GRID_SIZE * GRID_SIZE];
    int top = 0;

    stack_row[top] = start_row;
    stack_col[top] = start_col;
    top++;
    grid[start_row][start_col] = '.';

    while (top > 0) {
        top--;
        int row = stack_row[top];
        int col = stack_col[top];

        const int row_delta[4] = {-1, 1, 0, 0};
        const int col_delta[4] = {0, 0, -1, 1};

        for (int direction = 0; direction < 4; direction++) {
            int next_row = row + row_delta[direction];
            int next_col = col + col_delta[direction];

            if (is_inside(next_row, next_col) && grid[next_row][next_col] == '#') {
                grid[next_row][next_col] = '.';
                stack_row[top] = next_row;
                stack_col[top] = next_col;
                top++;
            }
        }
    }
}

static int count_regions(char grid[GRID_SIZE][GRID_SIZE + 1])
{
    int region_count = 0;

    for (int row = 0; row < GRID_SIZE; row++) {
        for (int col = 0; col < GRID_SIZE; col++) {
            if (grid[row][col] == '#') {
                region_count++;
                flood_fill(grid, row, col);
            }
        }
    }

    return region_count;
}

int main(void)
{
    char grid[GRID_SIZE][GRID_SIZE + 1];

    for (int row = 0; row < GRID_SIZE; row++) {
        if (scanf("%10s", grid[row]) != 1) {
            return 0;
        }
    }

    printf("%d\n", count_regions(grid));
    return 0;
}

