static int compute_lis_length(int count, const int *values) {
    int *best_length = malloc((size_t)count * sizeof *best_length);
    if (best_length == NULL) {
        return 0;
    }

    int max_length = 0;
    for (int i = 0; i < count; i++) {
        best_length[i] = 1;
        for (int j = 0; j < i; j++) {
            if (values[j] < values[i] && best_length[j] + 1 > best_length[i]) {
                best_length[i] = best_length[j] + 1;
            }
        }
        if (best_length[i] > max_length) {
            max_length = best_length[i];
        }
    }

    free(best_length);
    return max_length;
}

