}

int main(void) {
    int requested_count;

    if (!read_integer(&requested_count) || requested_count < 0) {
        return 1;
    }

    size_t count = 0;
    size_t capacity = 1;
    int *numbers = malloc(capacity * sizeof *numbers);

    if (numbers == NULL) {
        return 1;
    }

    for (int i = 0; i < requested_count; ++i) {
        int value;

        if (!read_integer(&value)) {
            free(numbers);
            return 1;
        }

        if (count == capacity) {
            size_t new_capacity = capacity * 2;
            int *grown_numbers = realloc(numbers, new_capacity * sizeof *grown_numbers);

            if (grown_numbers == NULL) {
                free(numbers);
                return 1;
            }

            numbers = grown_numbers;
            capacity = new_capacity;
        }

        numbers[count++] = value;
    }

    long long sum = 0;

    for (size_t i = 0; i < count; ++i) {
        sum += numbers[i];
    }

    printf("%lld\n", sum);
    free(numbers);
    return 0;
