#include <stdio.h>

struct Complex {
    double re;
    double im;
};

static struct Complex read_complex(void)
{
    struct Complex value;

    if (scanf("%lf %lf", &value.re, &value.im) != 2) {
        value.re = 0.0;
        value.im = 0.0;
    }

    return value;
}

static struct Complex multiply_complex(struct Complex left, struct Complex right)
{
    struct Complex result;

    result.re = left.re * right.re - left.im * right.im;
    result.im = left.re * right.im + left.im * right.re;

    return result;
}

static void print_complex(struct Complex value)
{
    printf("%.6f %.6f\n", value.re, value.im);
}

int main(void)
{
    struct Complex first = read_complex();
    struct Complex second = read_complex();
    struct Complex product = multiply_complex(first, second);

    print_complex(product);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *create_node(int value) {
    Node *node = malloc(sizeof *node);
    if (node == NULL) return NULL;
    node->value = value;
    node->next = NULL;
    return node;
}

static Node *build_list(int count) {
    Node *head = NULL;
    Node *tail = NULL;
    for (int i = 0; i < count; i++) {
        int value;
        if (scanf("%d", &value) != 1) break;
        Node *node = create_node(value);
        if (node == NULL) break;
        if (head == NULL) {
            head = node;
            tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
    }
    return head;
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

static void print_reversed(Node *head) {
    int count = 0;
    for (Node *p = head; p != NULL; p = p->next) count++;

    Node **stack = (count > 0)
        ? malloc((size_t)count * sizeof *stack)
        : NULL;
    if (count > 0 && stack == NULL) return;

    int top = 0;
    for (Node *p = head; p != NULL; p = p->next) {
        stack[top++] = p;
    }

    int first = 1;
    while (top > 0) {
        if (!first) putchar(' ');
        printf("%d", stack[--top]->value);
        first = 0;
    }
    putchar('\n');
    free(stack);
}

