#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

#define STACK_CAPACITY 256

typedef struct {
    int values[STACK_CAPACITY];
    size_t count;
} IntStack;

static void init_stack(IntStack *stack) {
    stack->count = 0;
}

static void push_value(IntStack *stack, int value) {
    if (stack->count == STACK_CAPACITY) {
        fprintf(stderr, "stack overflow\n");
        exit(EXIT_FAILURE);
    }
    stack->values[stack->count++] = value;
}

static int pop_value(IntStack *stack) {
    if (stack->count == 0) {
        fprintf(stderr, "stack underflow\n");
        exit(EXIT_FAILURE);
    }
    return stack->values[--stack->count];
}

static int apply_operator(char operator, int left, int right) {
    switch (operator) {
        case '+':
            return left + right;
        case '-':
            return left - right;
        case '*':
            return left * right;
        case '/':
            if (right == 0) {
                fprintf(stderr, "division by zero\n");
                exit(EXIT_FAILURE);
            }
            return left / right;
        default:
            fprintf(stderr, "invalid operator\n");
            exit(EXIT_FAILURE);
    }
}

static int evaluate_rpn(const char *expression) {
    IntStack stack;
    init_stack(&stack);

    for (size_t i = 0; expression[i] != '\0'; ++i) {
        char token = expression[i];

        if (isspace((unsigned char)token)) {
            continue;
        }

        if (isdigit((unsigned char)token)) {
            push_value(&stack, token - '0');
        } else if (token == '+' || token == '-' ||
                   token == '*' || token == '/') {
            int right_operand = pop_value(&stack);
            int left_operand = pop_value(&stack);
            push_value(&stack, apply_operator(token, left_operand, right_operand));
        } else {
            fprintf(stderr, "invalid character: %c\n", token);
            exit(EXIT_FAILURE);
        }
    }

    if (stack.count != 1) {
        fprintf(stderr, "invalid expression\n");
        exit(EXIT_FAILURE);
    }

    return pop_value(&stack);
}

static char *read_all_input(void) {
    size_t capacity = 256;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    int character;
    while ((character = getchar()) != EOF) {
        if (length + 1 >= capacity) {
            capacity *= 2;
            char *new_buffer = realloc(buffer, capacity);
            if (new_buffer == NULL) {
                free(buffer);
                perror("realloc");
                exit(EXIT_FAILURE);
            }
            buffer = new_buffer;
        }
        buffer[length++] = (char)character;
    }

    buffer[length] = '\0';
    return buffer;
}

int main(void) {
    char *expression = read_all_input();
    int result = evaluate_rpn(expression);

    printf("%d\n", result);
    free(expression);
    return 0;
}

#include <stdio.h>
#include <ctype.h>

static long parse_expression(void)
{
    long result = 0;
    long current = 0;
    int has_current = 0;
    int sign = 1;
    int c;

    while ((c = getchar()) != EOF) {
        if (isdigit((unsigned char)c)) {
            current = current * 10 + (c - '0');
            has_current = 1;
        } else if (c == '+' || c == '-') {
            if (has_current) {
                result += sign * current;
                current = 0;
                has_current = 0;
            }
            sign = (c == '+') ? 1 : -1;
        } else if (isspace((unsigned char)c)) {
            if (has_current) {
                result += sign * current;
                current = 0;
                has_current = 0;
                sign = 1;
            }
        }
    }

    if (has_current) {
        result += sign * current;
    }

    return result;
}

int main(void)
{
    long value = parse_expression();
    printf("%ld\n", value);
    return 0;
}

