static char *encode_look_and_say(const char *term) {
    size_t term_length = strlen(term);
    char *next_term = malloc(2 * term_length + 1);
    if (next_term == NULL) {
        return NULL;
    }

    size_t output_position = 0;
    size_t index = 0;
    while (index < term_length) {
        size_t run_start = index;
        while (index < term_length && term[index] == term[run_start]) {
            index++;
        }
        size_t run_length = index - run_start;

        char count_buffer[32];
        int count_length = snprintf(count_buffer, sizeof count_buffer, "%zu", run_length);
        if (count_length < 0) {
            free(next_term);
            return NULL;
        }

        memcpy(next_term + output_position, count_buffer, (size_t)count_length);
        output_position += (size_t)count_length;
        next_term[output_position++] = term[run_start];
    }

    next_term[output_position] = '\0';
    return next_term;
}

int main(void) {
    int term_count;
    if (scanf("%d", &term_count) != 1) {
        return 0;
    }
    if (term_count <= 0) {
        return 0;
    }

    char *current_term = malloc(2);
    if (current_term == NULL) {
        return 0;
    }
    strcpy(current_term, "1");

    for (int term_index = 0; term_index < term_count; term_index++) {
        puts(current_term);

        if (term_index + 1 < term_count) {
            char *next_term = encode_look_and_say(current_term);
            if (next_term == NULL) {
                free(current_term);
                return 0;
            }
            free(current_term);
            current_term = next_term;
        }
    }

    free(current_term);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define BYTE_VALUE_COUNT 256

static char *read_one_line(void)
{
    size_t capacity = 64;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return NULL;
    }

    int character;
    while ((character = getchar()) != EOF && character != '\n') {
        if (length + 1 >= capacity) {
            capacity *= 2;
            char *resized = realloc(buffer, capacity);
            if (resized == NULL) {
                free(buffer);
                return NULL;
            }
            buffer = resized;
        }
        buffer[length++] = (char)character;
    }

    if (character == EOF && length == 0) {
        free(buffer);
        return NULL;
    }

    if (length > 0 && buffer[length - 1] == '\r') {
        --length;
    }

    buffer[length] = '\0';
    return buffer;
}

static void count_bytes(const char *text, size_t length, size_t counts[BYTE_VALUE_COUNT])
{
    for (size_t i = 0; i < length; ++i) {
        counts[(unsigned char)text[i]]++;
    }
}

static int find_most_frequent(const size_t counts[BYTE_VALUE_COUNT], unsigned char *result_character)
{
    size_t maximum_count = 0;
    int found = 0;

    for (int value = 0; value < BYTE_VALUE_COUNT; ++value) {
        if (counts[value] > maximum_count) {
            maximum_count = counts[value];
            *result_character = (unsigned char)value;
            found = 1;
        }
    }

    return found ? (int)maximum_count : -1;
}

int main(void)
{
    char *line = read_one_line();

    if (line == NULL) {
        return 0;
    }

    size_t counts[BYTE_VALUE_COUNT] = {0};
    count_bytes(line, strlen(line), counts);

    unsigned char most_frequent_character = 0;
    int frequency = find_most_frequent(counts, &most_frequent_character);

    if (frequency > 0) {
        printf("%c %d\n", most_frequent_character, frequency);
    }

    free(line);
    return 0;
}

