static char *read_all(size_t *out_len) {
    size_t cap = 4096, len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) return NULL;

    for (;;) {
        if (len == cap) {
            size_t new_cap = cap * 2;
            char *tmp = realloc(buf, new_cap);
            if (tmp == NULL) {
                free(buf);
                return NULL;
            }
            buf = tmp;
            cap = new_cap;
        }
        size_t got = fread(buf + len, 1, cap - len, stdin);
        if (got == 0) break;
        len += got;
        if (ferror(stdin)) {
            free(buf);
            return NULL;
        }
    }

    if (len == cap) {
        char *tmp = realloc(buf, cap + 1);
        if (tmp == NULL) {
            free(buf);
            return NULL;
        }
        buf = tmp;
    }
    buf[len] = '\0';
    *out_len = len;
    return buf;
}

