    size_t len = 0;
    char *buf = read_all(&len);
    if (buf == NULL) return 0;

    size_t i = 0;
    while (i < len && isspace((unsigned char)buf[i])) ++i;

    int negative = 0;
    if (i < len && (buf[i] == '-' || buf[i] == '+')) {
        if (buf[i] == '-') negative = 1;
        ++i;
    }

    size_t start = i;
    while (i < len && isdigit((unsigned char)buf[i])) ++i;
    size_t end = i;

    if (start == end) {
        free(buf);
        return 0;
    }

    size_t p = end;
    while (p > start && buf[p - 1] == '0') --p;

    if (p == start) {
        fputs("0\n", stdout);
        free(buf);
        return 0;
    }

    if (negative) fputc('-', stdout);
    for (size_t j = p; j-- > start; ) {
        fputc(buf[j], stdout);
    }
    fputc('\n', stdout);

    free(buf);
    return 0;
}

