int main(void) {
    size_t len = 0;
    char *input = read_all_stdin(&len);
    if (input == NULL) {
        return 0;
    }

    const char *p = input;
    while (*p != '\0' && isspace((unsigned char)*p)) {
        ++p;
    }

    int negative = 0;
    if (*p == '+' || *p == '-') {
        negative = (*p == '-');
        ++p;
    }

    if (!isdigit((unsigned char)*p)) {
        free(input);
        return 0;
    }

    unsigned long long magnitude = 0;
    int has_digit = 0;
    while (isdigit((unsigned char)*p)) {
        has_digit = 1;
        magnitude = magnitude * 10ULL + (unsigned long long)(*p - '0');
        ++p;
    }

    if (!has_digit) {
        free(input);
        return 0;
    }

    if (negative && magnitude != 0ULL) {
