#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    size_t capacity = 0;
    size_t length = 0;
    char *buffer = NULL;
    int c;

    while ((c = fgetc(stdin)) != EOF) {
        if (length + 1 > capacity) {
            size_t new_capacity = capacity ? capacity * 2 : 64;
            if (new_capacity < length + 1) {
                new_capacity = length + 1;
            }
            char *tmp = realloc(buffer, new_capacity);
            if (tmp == NULL) {
                free(buffer);
                return 1;
            }
            buffer = tmp;
            capacity = new_capacity;
        }
        buffer[length++] = (char)c;
    }

    int had_newline = length > 0 && buffer[length - 1] == '\n';
    if (had_newline) {
        --length;
    }

    for (size_t i = length; i > 0; --i) {
        putchar(buffer[i - 1]);
    }
    if (had_newline) {
        putchar('\n');
    }

    free(buffer);
    return 0;
}

