#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

int main(void)
{
    size_t cap = 4096;
    size_t len = 0;
    char *buf = malloc(cap);

    if (buf == NULL) {
        return 1;
    }

    for (;;) {
        if (len == cap) {
            if (cap > (SIZE_MAX / 2)) {
                free(buf);
                return 1;
            }
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (tmp == NULL) {
                free(buf);
                return 1;
            }
            buf = tmp;
        }

        size_t n = fread(buf + len, 1, cap - len, stdin);
        len += n;

        if (n < cap - len + n) {
            /* n < requested bytes: EOF or error */
            break;
        }
    }

    if (ferror(stdin)) {
        free(buf);
        return 1;
    }

    size_t best_start = 0;
    size_t best_len = 0;
    size_t i = 0;

    while (i < len) {
        while (i < len && isspace((unsigned char)buf[i])) {
            ++i;
        }
        size_t start = i;
        while (i < len && !isspace((unsigned char)buf[i])) {
            ++i;
        }
        size_t word_len = i - start;
        if (word_len > best_len) {
            best_len = word_len;
            best_start = start;
        }
    }

    if (best_len > 0) {
        fwrite(buf + best_start, 1, best_len, stdout);
    }
    putchar('\n');

    free(buf);
    return 0;
}

