#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    unsigned char *digits;
    size_t len;
    size_t cap;
} BigInt;

static void bi_reserve(BigInt *a, size_t n)
{
    if (a->cap >= n) return;
    size_t newcap = a->cap ? a->cap : 16;
    while (newcap < n) newcap *= 2;
    unsigned char *p = realloc(a->digits, newcap);
    if (!p) {
        perror("realloc");
        exit(EXIT_FAILURE);
    }
    memset(p + a->cap, 0, newcap - a->cap);
    a->digits = p;
    a->cap = newcap;
}

static void bi_push(BigInt *a, unsigned char v)
{
    bi_reserve(a, a->len + 1);
    a->digits[a->len++] = v;
}

static void bi_mul_small(BigInt *a, unsigned m)
{
    unsigned carry = 0;
    for (size_t i = 0; i < a->len; ++i) {
        unsigned t = a->digits[i] * m + carry;
        a->digits[i] = (unsigned char)(t % 10);
        carry = t / 10;
    }
    while (carry) {
        bi_push(a, (unsigned char)(carry % 10));
        carry /= 10;
    }
}

static void bi_add_small(BigInt *a, unsigned x)
{
    size_t i = 0;
    unsigned carry = x;
    while (carry) {
        if (i == a->len) bi_push(a, 0);
        unsigned t = a->digits[i] + carry;
        a->digits[i] = (unsigned char)(t % 10);
        carry = t / 10;
        ++i;
    }
}

static int hex_value(char c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static char *read_line(void)
{
    size_t cap = 0, len = 0;
    char *buf = NULL;
    int c;

    while ((c = fgetc(stdin)) != EOF) {
        if (c == '\n') break;
        if (len + 1 >= cap) {
            size_t newcap = cap ? cap * 2 : 256;
            char *p = realloc(buf, newcap);
            if (!p) {
                perror("realloc");
                exit(EXIT_FAILURE);
            }
            buf = p;
            cap = newcap;
        }
        buf[len++] = (char)c;
    }

    if (!buf) {
        buf = calloc(1, 1);
        if (!buf) {
            perror("calloc");
            exit(EXIT_FAILURE);
        }
    } else {
        buf[len] = '\0';
    }
    return buf;
}

int main(void)
{
    char *line = read_line();

    BigInt num;
    num.digits = malloc(1);
    if (!num.digits) {
        perror("malloc");
        free(line);
        return EXIT_FAILURE;
    }
    num.digits[0] = 0;
    num.len = 1;
    num.cap = 1;

    const char *p = line;
    while (isspace((unsigned char)*p)) ++p;
    if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) p += 2;

    for (; *p; ++p) {
        if (isspace((unsigned char)*p)) continue;
        int v = hex_value(*p);
        if (v < 0) break;
        bi_mul_small(&num, 16);
        bi_add_small(&num, (unsigned)v);
    }

    for (size_t i = num.len; i > 0; --i)
        putchar((int)('0' + num.digits[i - 1]));
    putchar('\n');

    free(num.digits);
    free(line);
    return EXIT_SUCCESS;
}

