static void merge(int a[], int tmp[], int left, int mid, int right) {
    int i = left;
    int j = mid + 1;
    int k = left;

    while (i <= mid && j <= right) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];
        } else {
            tmp[k++] = a[j++];
        }
    }
    while (i <= mid) {
        tmp[k++] = a[i++];
    }
    while (j <= right) {
        tmp[k++] = a[j++];
    }
    for (i = left; i <= right; i++) {
        a[i] = tmp[i];
    }
}

static void merge_sort_range(int a[], int tmp[], int left, int right) {
    if (left >= right) {
        return;
    }
    int mid = left + (right - left) / 2;
    merge_sort_range(a, tmp, left, mid);
    merge_sort_range(a, tmp, mid + 1, right);
    merge(a, tmp, left, mid, right);
}

static void merge_sort(int a[], int n) {
    if (n <= 1) {
        return;
    }
    int *tmp = malloc((size_t)n * sizeof(int));
    if (tmp == NULL) {
        return;
    }
    merge_sort_range(a, tmp, 0, n - 1);
    free(tmp);
}

