#include <stdio.h>
#include <stdlib.h>

static void sift_down(int *a, size_t n, size_t root) {
    size_t parent = root;

    while (2 * parent + 1 < n) {
        size_t child = 2 * parent + 1;

        if (child + 1 < n && a[child] < a[child + 1]) {
            child++;
        }
        if (a[parent] >= a[child]) {
            break;
        }

        int tmp = a[parent];
        a[parent] = a[child];
        a[child] = tmp;
        parent = child;
    }
}

static void heap_sort(int *a, size_t n) {
    if (n < 2) {
        return;
    }

    for (size_t i = n / 2; i-- > 0; ) {
        sift_down(a, n, i);
    }

    for (size_t end = n; end > 1; end--) {
        int tmp = a[0];
        a[0] = a[end - 1];
        a[end - 1] = tmp;
        sift_down(a, end - 1, 0);
    }
}

