#include <stdlib.h>
#include <stdint.h>

static int cmp_int(const void *a, const void *b)
{
    const int *pa = a;
    const int *pb = b;
    return (*pa > *pb) - (*pa < *pb);
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1)
        return 0;

    if (n <= 0)
        return 0;

    size_t count = (size_t)n;
    if (count > SIZE_MAX / sizeof(int))
        return 0;

    int *values = malloc(count * sizeof(*values));
    if (values == NULL)
        return 0;

    size_t read = 0;
    for (size_t i = 0; i < count; ++i) {
        if (scanf("%d", &values[i]) != 1) {
            read = i;
            break;
        }
        read = i + 1;
    }

    if (read == 0) {
        free(values);
        return 0;
    }

    qsort(values, read, sizeof(*values), cmp_int);

    for (size_t i = 0; i < read; ) {
        size_t j = i + 1;
        while (j < read && values[j] == values[i])
            ++j;
        printf("%d %d\n", values[i], (int)(j - i));
        i = j;
    }

    free(values);
    return 0;
}

#include <stdio.h>

int main(void) {
    char grid[10][10];
    for (int i = 0; i < 10; i++)
        for (int j = 0; j < 10; j++)
            grid[i][j] = '.';

    int n = 0;
    int c;
    while ((c = getchar()) != EOF && n < 100) {
        if (c == '.' || c == '#') {
            grid[n / 10][n % 10] = (char)c;
            n++;
        }
    }

    int count = 0;
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            if (grid[i][j] != '#')
                continue;

            count++;
            int q[100];
            int head = 0, tail = 0;
            q[tail++] = i * 10 + j;
            grid[i][j] = '.';

            while (head < tail) {
                int pos = q[head++];
                int r = pos / 10;
                int col = pos % 10;

                int dr[4] = {-1, 1, 0, 0};
                int dc[4] = {0, 0, -1, 1};

                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d];
                    int nc = col + dc[d];
                    if (nr < 0 || nr >= 10 || nc < 0 || nc >= 10)
                        continue;
                    if (grid[nr][nc] != '#')
                        continue;
                    grid[nr][nc] = '.';
                    q[tail++] = nr * 10 + nc;
                }
            }
        }
    }

    printf("%d\n", count);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;

    if (scanf("%d", &n) != 1) {
        printf("0\n");
        return 0;
    }

    if (n <= 0) {
        printf("0\n");
        return 0;
    }

    int *a = malloc((size_t)n * sizeof *a);
    int *dp = malloc((size_t)n * sizeof *dp);
    if (a == NULL || dp == NULL) {
        free(a);
        free(dp);
        printf("0\n");
        return 0;
    }

    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &a[i]) != 1) {
            a[i] = 0;
        }
    }

    int best = 0;
    for (int i = 0; i < n; ++i) {
        dp[i] = 1;
        for (int j = 0; j < i; ++j) {
            if (a[j] < a[i] && dp[j] + 1 > dp[i]) {
                dp[i] = dp[j] + 1;
            }
        }
        if (dp[i] > best) {
            best = dp[i];
        }
    }

    printf("%d\n", best);

    free(a);
    free(dp);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

int main(void) {
    int n;

    if (scanf("%d", &n) != 1 || n <= 0) {
        printf("0\n");
        return 0;
    }

    int64_t best = 0, cur = 0, x = 0;
    int have_value = 0;

    for (int i = 0; i < n; i++) {
        if (scanf("%" SCNd64, &x) != 1) {
            break;
        }

        if (!have_value) {
            best = cur = x;
            have_value = 1;
        } else {
            cur = x > cur + x ? x : cur + x;
            if (cur > best) {
                best = cur;
            }
        }
    }

    if (!have_value) {
        printf("0\n");
    } else {
        printf("%" PRId64 "\n", best);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    return (x > y) - (x < y);
}

int main(void) {
    long long n, capacity;

    if (scanf("%lld %lld", &n, &capacity) != 2) {
        printf("0\n");
        return 0;
    }

    if (n <= 0) {
        printf("0\n");
        return 0;
    }

    long long *weights = malloc((size_t)n * sizeof(*weights));
    if (!weights) {
        printf("0\n");
        return 0;
    }

    for (long long i = 0; i < n; i++) {
        if (scanf("%lld", &weights[i]) != 1) {
            weights[i] = 0;
        }
    }

    qsort(weights, (size_t)n, sizeof(*weights), cmp_ll);

    long long used = 0;
    long long count = 0;
    for (long long i = 0; i < n; i++) {
        if (used + weights[i] <= capacity) {
            used += weights[i];
            count++;
        } else {
            break;
        }
    }

    printf("%lld\n", count);
    free(weights);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    long long n;

    if (scanf("%lld", &n) != 1) {
        printf("0\n");
        return 0;
    }

    if (n < 0) {
        n = 0;
    }

    size_t capacity = 1;
    size_t size = 0;
    int *array = malloc(capacity * sizeof *array);

    if (array == NULL) {
        fprintf(stderr, "malloc failed\n");
        return 1;
    }

    long long sum = 0;

    for (long long i = 0; i < n; ++i) {
        if (size == capacity) {
            if (capacity > ((size_t)-1) / 2) {
                fprintf(stderr, "capacity overflow\n");
                free(array);
                return 1;
            }

            size_t new_capacity = capacity * 2;
            int *new_array = realloc(array, new_capacity * sizeof *new_array);

            if (new_array == NULL) {
                fprintf(stderr, "realloc failed\n");
                free(array);
                return 1;
            }

            array = new_array;
            capacity = new_capacity;
        }

        int value;

        if (scanf("%d", &value) != 1) {
            break;
        }

        array[size++] = value;
        sum += value;
    }

    printf("%lld\n", sum);
    free(array);
    return 0;
}

