#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

struct Complex {
    double re;
    double im;
};

static char *read_all_stdin(void) {
    size_t cap = 4096;
    size_t len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) {
        return NULL;
    }

    for (;;) {
        if (len == cap) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (tmp == NULL) {
                free(buf);
                return NULL;
            }
            buf = tmp;
        }
        size_t n = fread(buf + len, 1, cap - len, stdin);
        if (n == 0) {
            break;
        }
        len += n;
    }

    if (ferror(stdin)) {
        free(buf);
        return NULL;
    }

    buf[len] = '\0';
    return buf;
}

static char *normalize_input(const char *s) {
    size_t len = strlen(s);
    char *out = malloc(len * 2 + 1);
    if (out == NULL) {
        return NULL;
    }

    size_t j = 0;
    for (size_t i = 0; s[i] != '\0'; i++) {
        unsigned char c = (unsigned char)s[i];
        if (c == ',' || c == 'i' || c == 'I' || c == 'j' || c == 'J' ||
            c == '(' || c == ')' || c == '[' || c == ']' ||
            c == '{' || c == '}') {
            out[j++] = ' ';
        } else if (isdigit(c) || c == '.' || c == '+' || c == '-' ||
                   c == 'e' || c == 'E' || isspace(c)) {
            out[j++] = (char)c;
        } else {
            out[j++] = ' ';
        }
    }
    out[j] = '\0';
    return out;
}

int main(void) {
    char *raw = read_all_stdin();
    if (raw == NULL) {
        return 1;
    }

    char *text = normalize_input(raw);
    free(raw);
    if (text == NULL) {
        return 1;
    }

    double vals[4] = {0.0, 0.0, 0.0, 0.0};
    int count = 0;
    char *p = text;

    while (count < 4) {
        while (*p != '\0' && isspace((unsigned char)*p)) {
            p++;
        }
        if (*p == '\0') {
            break;
        }

        char *end = NULL;
        double x = strtod(p, &end);
        if (end == p) {
            p++;
            continue;
        }

        vals[count++] = x;
        p = end;
    }

    free(text);

    if (count == 0) {
        return 0;
    }

    struct Complex a;
    struct Complex b;

    if (count == 1) {
        a.re = vals[0];
        a.im = 0.0;
        b.re = 0.0;
        b.im = 0.0;
    } else if (count == 2) {
        a.re = vals[0];
        a.im = 0.0;
        b.re = vals[1];
        b.im = 0.0;
    } else if (count == 3) {
        a.re = vals[0];
        a.im = vals[1];
        b.re = vals[2];
        b.im = 0.0;
    } else {
        a.re = vals[0];
        a.im = vals[1];
        b.re = vals[2];
        b.im = vals[3];
    }

    struct Complex product;
    product.re = a.re * b.re - a.im * b.im;
    product.im = a.re * b.im + a.im * b.re;

    printf("%.10g %.10g\n", product.re, product.im);
    return 0;
}
